use serde_json::{json,Value};
use ss_core::{java_runtime::{Rc,DecimalInteger::{characterDigit,parseInt,parseLong}},cn::wps::et::ss::{constant::{RecogniseOption::RecogniseOption,NumfmtCategory::NumfmtCategory},multlang::res::{DigitsRes::DigitsRes,DigitsResResult::DigitsResResult}}};
use util::org::apache::poi::util::LanguageType::{LanguageType,LANGUAGE_FRENCH};
fn decode(v:&Value)->Option<Vec<u16>>{v.as_str().map(|s|(0..s.len()).step_by(4).map(|i|u16::from_str_radix(&s[i..i+4],16).unwrap()).collect())}
fn hex(v:&[u16])->String{v.iter().map(|c|format!("{c:04x}")).collect()}
fn fields(o:&RecogniseOption)->Value{json!({"keep":o.keepTailZero,"force":o.forceText,"date1904":o.date1904,"numfmt":format!("{:?}",o.preferedNumfmt),"language":o.language.name()})}
fn decode64(s:&str)->Vec<u8>{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=vec![];let(mut value,mut bits)=(0u32,0);for c in s.bytes(){if c==b'='{break;}value=(value<<6)|alphabet.iter().position(|b|*b==c).unwrap()as u32;bits+=6;if bits>=8{bits-=8;out.push((value>>bits)as u8);value&=(1<<bits)-1;}}out}
fn encode64(s:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in s.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
#[test]
fn original_android_digits_options_and_decimal_integer(){
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/recognise-r0b27");
    let expected:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let mut options=vec![];
    let cats=[NumfmtCategory::NONE,NumfmtCategory::GENERAL,NumfmtCategory::NUMBER,NumfmtCategory::ACCOUNTING,NumfmtCategory::CURRENCY,NumfmtCategory::DATE,NumfmtCategory::TIME,NumfmtCategory::DATE_TIME,NumfmtCategory::PERCENTAGE,NumfmtCategory::FRACTION,NumfmtCategory::SCIENTIC,NumfmtCategory::TEXT];
    for row in expected["options"].as_array().unwrap(){let input=&row["input"];let mut o=if input["default"]==true{RecogniseOption::RecogniseOption()}else{RecogniseOption::RecogniseOption__2(input["keep"].as_bool().unwrap(),input["force"].as_bool().unwrap(),input["date1904"].as_bool().unwrap(),*cats.iter().find(|c|format!("{c:?}")==input["numfmt"].as_str().unwrap()).unwrap(),LanguageType::valueOf(input["language"].as_str().unwrap()))};
        let before=fields(&o);let cached=o.getLangRes();o.setForceText(!o.forceText);o.language=LANGUAGE_FRENCH;let later=o.getLangRes();
        let actual=json!({"input":input,"before":before,"after":fields(&o),"sameResource":Rc::ptr_eq(&cached,&later),"cachedDateFormat":later.DATE.SHORT_DATE_NUMFMT});assert_eq!(actual,*row);options.push(actual);
    }
    let d=&expected["digits"];let mut flags=vec![];
    for row in d["flags"].as_array().unwrap(){let f=row["flag"].as_i64().unwrap()as i32;
        let actual=json!({"flag":f,"mix":DigitsRes::isMix(f),"common":DigitsRes::isCommon(f),"arabic":DigitsRes::isArabic(f),"tai":DigitsRes::isTai(f),"hindi":DigitsRes::isHindi(f),"korean":DigitsRes::isKorean(f),"contains":[DigitsRes::containCommon(f),DigitsRes::containArabic(f),DigitsRes::containTai(f),DigitsRes::containHindi(f),DigitsRes::containKorean(f)],"addCommon":DigitsRes::addCommon(f),"add":(-1..=5).map(|i|DigitsRes::addFlag(i,f)).collect::<Vec<_>>()});assert_eq!(actual,*row);flags.push(actual);
    }
    let mut translated=vec![];for row in d["translate"].as_array().unwrap(){let s=decode(&row["text"]).unwrap();let digits=decode(&row["digits"]).unwrap();let r=std::panic::catch_unwind(||DigitsRes::translateDigits(&s,&digits));
        let mut actual=json!({"text":row["text"],"digits":row["digits"]});match r{Ok(r)=>actual["out"]=json!(hex(&r)),Err(_)=>actual["exception"]=json!("AssertionError")};assert_eq!(actual,*row);translated.push(actual);
    }
    let mut differences=vec![];for row in d["differences"].as_array().unwrap(){let a=decode(&row["a"]);let b=decode(&row["b"]);let mut r=DigitsResResult::new();r.setContent(a.as_deref());let actual=json!({"a":row["a"],"b":row["b"],"completeDiff":r.completeDiff(b.as_deref()),"diff":r.diff(b.as_deref())});assert_eq!(actual,*row);differences.push(actual);}
    let mut results=vec![];for row in d["results"].as_array().unwrap(){let s=decode(&row["text"]);let mut r=DigitsResResult::new();r.setContent(s.as_deref());r.flag=row["flag"].as_i64().unwrap()as i32;let mut actual=json!({"text":row["text"],"flag":r.flag});
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(||r.getResult())){Ok(Some(v))=>actual["result"]=json!({"bits":format!("{:016x}",v.getDblValue().unwrap().to_bits()),"flags":0,"formatIndex":v.getBuiltInNumfmtIdx(),"format":v.getSuggestedNumfmt()}),Ok(None)=>actual["result"]=Value::Null,Err(_)=>actual["exception"]=json!("NumberFormatException")};r.reset();actual["afterReset"]=json!(r.flag);actual["resetResult"]=json!(r.getResult().is_none());assert_eq!(actual,*row);results.push(actual);
    }
    let mut local=vec![];for row in d["localFormats"].as_array().unwrap(){let actual=json!({"input":row["input"],"out":DigitsResResult::isLocalNumberFmt(row["input"].as_str())});assert_eq!(actual,*row);local.push(actual);}
    let table=expected["characterDigits"].as_str().unwrap().as_bytes();let mut digits=String::new();assert_eq!(table.len(),65536);for (c,v)in table.iter().enumerate(){let expected=if *v==b'.'{-1}else{(*v-b'0')as i32};let actual=characterDigit(c as u16);assert_eq!(actual,expected,"char {c:04x}");assert_eq!(parseInt(&[c as u16]),if expected<0{None}else{Some(expected)});digits.push(if actual<0{'.'}else{(actual as u8+b'0')as char});}
    let mut runtime=serde_json::Map::new();for (key,upper)in [("characterLower",false),("characterUpper",true)]{let expected=decode64(expected[key].as_str().unwrap());let mut actual=vec![];for c in 0..65536{let value=if upper{ss_core::java_runtime::Character::toUpperCase(c as u16)}else{ss_core::java_runtime::Character::toLowerCase(c as u16)};actual.extend_from_slice(&value.to_le_bytes());}assert_eq!(actual,expected);runtime.insert(key.into(),json!(encode64(&actual)));}
    let mut preprocessed=vec![];for (c,row)in expected["preprocessChars"].as_array().unwrap().iter().enumerate(){let actual=ss_core::cn::wps::et::ss::constant::ConstRecognisor::ConstRecognisor::preprocessConstRecognize(&[c as u16]).map_or(Value::Null,|s|json!(hex(&s)));assert_eq!(actual,*row,"preprocess char {c:04x}");preprocessed.push(actual);}
    for cls in ["d","w","s"]{let key=format!("regex{cls}");let expected=decode64(expected[&key].as_str().unwrap());let regex=ss_core::java_runtime::Pattern::compileMatches(&format!(r"\{cls}"),false).unwrap();let mut actual=vec![0u8;0x110000/8];for c in 0..0x110000{let mut buf=[0;4];let member=char::from_u32(c).is_some_and(|ch|regex.is_match(ch.encode_utf8(&mut buf)));if member{actual[c as usize/8]|=1<<(c%8);}assert_eq!(member,expected[c as usize/8]&(1<<(c%8))!=0,"regex {cls} code point {c:x}");}runtime.insert(key,json!(encode64(&actual)));}
    let mut parsed=vec![];for row in expected["parseNumbers"].as_array().unwrap(){let s=decode(&row["text"]).unwrap();let actual=json!({"text":row["text"],"int":parseInt(&s).map_or(json!("NumberFormatException"),|v|json!(v)),"long":parseLong(&s).map_or(json!("NumberFormatException"),|v|json!(v))});assert_eq!(actual,*row);parsed.push(actual);}
    let mut actual=json!({"options":options,"digits":{"flags":flags,"translate":translated,"differences":differences,"results":results,"localFormats":local},"characterDigits":digits,"parseNumbers":parsed,"preprocessChars":preprocessed});actual.as_object_mut().unwrap().extend(runtime);let mut expected=expected;for key in ["fractions","currencies","dateParts","dates","times","const","rawOnly","opcw"]{expected.as_object_mut().unwrap().remove(key);}assert_eq!(actual,expected);std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
